<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Usecase\Update;

use RuntimeException;

use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class ThemeUpdateCheck
{
  public function __construct(public readonly ThemeUpdateParams $input,     public readonly Theme $current)
  {
  }
  public function reject(RuntimeException|ConstraintFail $fail): void
  {
    if( $fail instanceof ConstraintFail) {         throw ConstraintException::ofFail($fail);    } else {      throw $fail;    }  }
}
